def findN(sumNum):
    i = 0
    num = 0
    if sumNum < 0:
        sumNum = -sumNum
    while num <= sumNum:
        num += i
        i += 1
    num -= i - 1
    i -= 2
    if num == sumNum:
        print(i)
    else:
        diff = sumNum - num
        n = i + 1
        new_diff = n - diff
        if new_diff % 2 == 0:
            print(n)
        elif (n + 1) % 2 != 0:
            print(n + 1)
        else:
            print(n + 2)


x = int(input())
findN(x)

